    level: 6,
    schoolPtBr: "conjuração",
    ritual: false,
    castingTime: "1 ação",
    range: "150 metros",
    components: "V, S",
    duration: "Concentração, até 10 minutos",
    classes: ["sorcerer", "warlock", "wizard"],
    source: {"chapter": "Capítulo 11 — Magias", "printedPage": 269, "pdfPage": 268},
    description: "Você cria portais de teletransporte conectados que\npermanecem abertos pela duração. Escolha dois pontos no\nsolo que você possa ver, um ponto a até 3 metros de você e\noutro a até 150 metros de você. Um portal circular, com 3\nmetros de diâmetro, se abre em cada ponto. Se o portal se\nabriria num local ocupado por uma criatura, a magia\nfalha e a conjuração é perdida.\nOs portais são dois anéis dimensionais brilhantes\ncheios de névoa, flutuando a centímetros do chão,\nperpendicular a ele no ponto escolhido. Um anel é visível\napenas de um lado (à sua escolha), que é o lado que\nfunciona como portal.\nQualquer criatura ou objeto que adentrar o portal,\nsairá pelo outro portal, como se ambos estivessem\nadjacentes um ao outro; atravessar um portal do lado que\nnão é um portal não tem efeito. A névoa que preenche\ncada portal é opaca e bloqueia a visão através dele. No\nseu turno, você pode girar os anéis, com uma ação bônus,\nfazendo o lado ativo ficar em uma direção diferente.",
    listAppearances: [{"classId": "warlock", "level": 6, "schoolPtBr": "conjuração", "ritual": false}, {"classId": "sorcerer", "level": 6, "schoolPtBr": "conjuração", "ritual": false}, {"classId": "wizard", "level": 6, "schoolPtBr": "conjuração", "ritual": false}],
